const listStaleMemoryConsolidations = `-- name: ListStaleMemoryConsolidations :many
SELECT c.id, c.company_id, c.workspace_id, c.workspace_slug, c.task_id, c.run_id, c.origin, c.scheduled_for, c.status, c.summary, c.created_at, c.finished_at FROM memory_consolidations c
WHERE c.status = 'open' AND c.created_at < $1
  AND NOT EXISTS (SELECT 1 FROM runs r WHERE r.task_id = c.task_id AND r.status IN ('queued','running'))
ORDER BY c.created_at
LIMIT $2
`

type ListStaleMemoryConsolidationsParams struct {
	Before time.Time
	Lim    int32
}

