func (q *Queries) ListStaleMemoryConsolidations(ctx context.Context, arg ListStaleMemoryConsolidationsParams) ([]MemoryConsolidation, error) {
	rows, err := q.db.Query(ctx, listStaleMemoryConsolidations, arg.Before, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MemoryConsolidation{}
	for rows.Next() {
		var i MemoryConsolidation
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.WorkspaceID,
			&i.WorkspaceSlug,
			&i.TaskID,
			&i.RunID,
			&i.Origin,
			&i.ScheduledFor,
			&i.Status,
			&i.Summary,
			&i.CreatedAt,
			&i.FinishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

