const upsertMemoryGrant = `-- name: UpsertMemoryGrant :one
INSERT INTO memory_grants (company_id, persona_id, workspace_id, access, created_at)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (persona_id, workspace_id) DO UPDATE SET access = EXCLUDED.access
RETURNING company_id, persona_id, workspace_id, access, created_at
`

type UpsertMemoryGrantParams struct {
	CompanyID   uuid.UUID
	PersonaID   uuid.UUID
	WorkspaceID uuid.UUID
	Access      string
	Now         time.Time
}

func (q *Queries) UpsertMemoryGrant(ctx context.Context, arg UpsertMemoryGrantParams) (MemoryGrant, error) {
	row := q.db.QueryRow(ctx, upsertMemoryGrant,
		arg.CompanyID,
		arg.PersonaID,
		arg.WorkspaceID,
		arg.Access,
		arg.Now,
	)
	var i MemoryGrant
	err := row.Scan(
		&i.CompanyID,
		&i.PersonaID,
		&i.WorkspaceID,
		&i.Access,
		&i.CreatedAt,
	)
	return i, err
}

